(() => { const st = G.stage.part('stream'); const p = N.controller.pos; window.__tried = window.__tried || [];
  const all = []; for (const ch of st.loaded.values()) for (const d of ch.doors) if (Math.hypot(d.x - p.x, d.z - p.z) < 60) all.push(d); const ds = all.filter((d) => !window.__tried.some((t) => Math.hypot(t.x - d.x, t.z - d.z) < 6));
  ds.sort((a, b) => Math.hypot(a.x - p.x, a.z - p.z) - Math.hypot(b.x - p.x, b.z - p.z));
  const d = ds[Math.min(ds.length - 1, 1)]; window.__door = d; window.__tried.push(d);
  return [[d.x + d.nx * 1.3, d.z + d.nz * 1.3]]; })()

